UPDATE file_upload
SET status = #{status}
WHERE file_md5 = #{fileMd5}

UPDATE file_upload
SET merged_at = CURRENT_TIMESTAMP
WHERE file_md5 = #{fileMd5}

UPDATE file_upload
SET file_name = #{fileName}
WHERE file_md5 = #{fileMd5}

UPDATE file_upload
SET is_public = #{isPublic}
WHERE file_md5 = #{fileMd5}
